    events = {**metadata, "schema_version": "bigsmall.r289.session-events.v1",
              "records": state["records"], "drops_by_reason": state["drops_by_reason"]}
    summary = {**metadata, "schema_version": "bigsmall.r289.session-summary.v1",
               "normal_sessionfinish_observed": True,
